pragma cashscript ^0.14.0;
// GENERATED by scripts/compile-registry.mjs from Registry.template.cash and pinned child opcodes.
// Inputs: 0 registry NFT, 1 token pool, [2 owner-signed registration funding].
// Outputs: 0 registry NFT, 1 token pool, [2 reward/refund], [3 independent allocation].
// State: period(4), phase(1), count(1), live(16*49), snapshot(16*49).
// Record: pubkey(33), S token units(4), T periods(4), R BCH sats(4), W(1), wins(1), cancelled(1), refunded(1).
contract Registry(bytes32 category, bytes32 stakingCategory, int epoch, int periodSeconds, int periods, int cap) {
    function transition(bytes state, int action, int slot, bytes record, sig authorization) {
        require(this.activeInputIndex == 0);
        require(epoch >= 500000000 && periodSeconds > 0);
        require(periods > 0 && periods <= 16 && cap >= 1000 && cap <= 1000000);
        // Four-byte positive Script numbers, including the latest possible maturity.
        require(epoch + (2 * periods - 1) * periodSeconds <= 2147483647);
        require(state.length == 1574);
        require(tx.inputs[0].nftCommitment == hash256(state));
        require(tx.inputs[0].tokenCategory == category + 0x01);
        require(tx.inputs[0].tokenAmount == 0);
        require(tx.outputs[0].lockingBytecode == tx.inputs[0].lockingBytecode);
        require(tx.outputs[0].tokenCategory == category + 0x01);
        require(tx.outputs[0].tokenAmount == 0);
        bytes poolScript = new LockingBytecodeP2SH32(hash256(0x40 + category + stakingCategory + 0xc0519d00ce7801207f75517e8800d17c01207f75517e8800cd00c787));
        require(tx.inputs[1].lockingBytecode == poolScript);
        require(tx.outputs[1].lockingBytecode == poolScript);
        require(tx.inputs[1].value == 1000 && tx.outputs[1].value == 1000);
        require(tx.inputs[1].nftCommitment == 0x && tx.outputs[1].nftCommitment == 0x);
        int period = int(state.slice(0,4));
        int phase = int(state.slice(4,5));
        int count = int(state.slice(5,6));
        require(period >= 0 && period <= periods);
        require(count >= 0 && count <= 16);
        require(phase == 0 || phase == 1);
        bytes live = state.slice(6,790);
        bytes snapshot = state.slice(790,1574);
        bytes next = state;
        int value = tx.inputs[0].value - 10000;
        int remainingBefore = 0;
        for (int n = 0; n < 16; n++) {
            if (n < count && live.slice(n*49+48,n*49+49) == 0x00) {
                remainingBefore = remainingBefore + int(live.slice(n*49+33,n*49+37))
                    * (int(live.slice(n*49+45,n*49+46)) - int(live.slice(n*49+46,n*49+47)));
            }
        }
        require(tx.inputs[1].tokenAmount == remainingBefore);
        if (remainingBefore == 0) { require(tx.inputs[1].tokenCategory == 0x); }
        else { require(tx.inputs[1].tokenCategory == stakingCategory); }
        if (action == 0) {
            require(phase == 0 && count < 16 && period < periods);
            require(slot == count);
            require(record.length == 49);
            int s = int(record.slice(33,37));
            int t = int(record.slice(37,41));
            int r = int(record.slice(41,45));
            int maximum = int(record.slice(45,46));
            require(s >= 1000 && s <= 1000000);
            require(t > 0 && t <= periods);
            require(r >= 1000 && r <= cap && cap <= 1000000);
            require(maximum > 0 && maximum <= periods);
            require(record.slice(46,49) == 0x000000);
            require(checkSig(authorization, pubkey(record.slice(0,33))));
            require(tx.inputs.length == 3 && tx.outputs.length == 2);
            require(tx.inputs[2].value == 10000);
            require(tx.inputs[2].tokenCategory == stakingCategory);
            require(tx.inputs[2].nftCommitment == 0x);
            require(tx.inputs[2].tokenAmount == s * maximum);
            value = tx.inputs[0].value;
            live = live.slice(0,slot*49) + record + live.slice((slot+1)*49,784);
            next = state.slice(0,5) + toPaddedBytes(count + 1, 1) + live + snapshot;
        } else if (action == 1) {
            require(tx.inputs.length == 2 && tx.outputs.length == 2);
            require(slot >= 0 && slot < count);
            bytes entry = live.slice(slot*49,(slot+1)*49);
            require(checkSig(authorization, pubkey(entry.slice(0,33))));
            require(entry.slice(47,48) == 0x00);
            live = live.slice(0,slot*49+47) + 0x01 + live.slice(slot*49+48,784);
            next = state.slice(0,6) + live + snapshot;
        } else if (action == 2) {
            require(tx.inputs.length == 2 && tx.outputs.length == 2);
            require(phase == 0 && period < periods);
            require(tx.time >= epoch + period * periodSeconds);
            next = state.slice(0,4) + 0x01 + state.slice(5,6) + live + live;
        } else if (action == 3) {
            require(tx.inputs.length == 2 && tx.outputs.length == 4);
            require(phase == 1);
            require(slot >= 0 && slot < count);
            bytes winner = snapshot.slice(slot*49,(slot+1)*49);
            int s = int(winner.slice(33,37));
            int t = int(winner.slice(37,41));
            int r = int(winner.slice(41,45));
            require(winner.slice(47,49) == 0x0000);
            require(int(winner.slice(46,47)) < int(winner.slice(45,46)));
            for (int i = 0; i < 16; i++) {
                if (i < count) {
                    bytes candidate = snapshot.slice(i*49,(i+1)*49);
                    if (candidate.slice(47,49) == 0x0000 && int(candidate.slice(46,47)) < int(candidate.slice(45,46))) {
                        int left = s * t * int(candidate.slice(41,45));
                        int right = int(candidate.slice(33,37)) * int(candidate.slice(37,41)) * r;
                        require(left >= right);
                        if (i < slot) { require(left > right); }
                    }
                }
            }
            bytes entry = live.slice(slot*49,(slot+1)*49);
            // One win deducts exactly S from W*S escrow and creates a distinct immutable lock.
            live = live.slice(0,slot*49+46) + toPaddedBytes(int(entry.slice(46,47)) + 1, 1) + live.slice(slot*49+47,784);
            bytes terms = winner.slice(0,33) + category + toPaddedBytes(slot, 1)
                + toPaddedBytes(period, 4) + toPaddedBytes(s, 4)
                + toPaddedBytes(epoch + (period + t) * periodSeconds, 4) + stakingCategory;
            require(tx.outputs[3].lockingBytecode == new LockingBytecodeP2SH32(hash256(0x4c6e + terms + 0xc0009dc3519cc4519c9a697d01217f75ad76014e7f75014a7f7781b17500c602d0079d00ce78016e7f75014e7f778800cf008800d078014a7f7501467f77819d00cd0376a914527901217f75a97e0288ac7e8800cc02e8039d00d178016e7f75014e7f778800d2008800d37c014a7f7501467f77819c)));
            require(tx.outputs[3].value == 2000);
            require(tx.outputs[3].tokenCategory == stakingCategory);
            require(tx.outputs[3].nftCommitment == 0x);
            require(tx.outputs[3].tokenAmount == s);
            next = toPaddedBytes(period + 1, 4) + 0x00 + state.slice(5,6) + live + snapshot;
            require(tx.outputs[2].lockingBytecode == new LockingBytecodeP2PKH(hash160(winner.slice(0,33))));
            require(tx.outputs[2].value == r && tx.outputs[2].tokenCategory == 0x);
            value = value - r - 2000;
        } else if (action == 5) {
            require(tx.inputs.length == 2 && tx.outputs.length == 2);
            require(phase == 1);
            for (int k = 0; k < 16; k++) {
                if (k < count) {
                    bytes candidate = snapshot.slice(k*49,(k+1)*49);
                    require(candidate.slice(47,49) != 0x0000 || int(candidate.slice(46,47)) >= int(candidate.slice(45,46)));
                }
            }
            next = toPaddedBytes(period + 1, 4) + 0x00 + state.slice(5,6) + live + snapshot;
        } else {
            require(action == 4);
            require(tx.inputs.length == 2 && tx.outputs.length == 3);
            require(phase == 0 && slot >= 0 && slot < count);
            bytes entry = live.slice(slot*49,(slot+1)*49);
            require(checkSig(authorization, pubkey(entry.slice(0,33))));
            require(entry.slice(47,49) == 0x0100);
            int refund = int(entry.slice(33,37)) * (int(entry.slice(45,46)) - int(entry.slice(46,47)));
            require(refund > 0);
            live = live.slice(0,slot*49+48) + 0x01 + live.slice(slot*49+49,784);
            next = state.slice(0,6) + live + snapshot;
            require(tx.outputs[2].lockingBytecode == new LockingBytecodeP2PKH(hash160(entry.slice(0,33))));
            require(tx.outputs[2].value == 1000);
            require(tx.outputs[2].tokenCategory == stakingCategory && tx.outputs[2].nftCommitment == 0x);
            require(tx.outputs[2].tokenAmount == refund);
            value = value - 1000;
        }
        int collateral = 0;
        for (int j = 0; j < 16; j++) {
            if (j < int(next.slice(5,6)) && next.slice(6+j*49+48,6+j*49+49) == 0x00) {
                collateral = collateral + int(next.slice(6+j*49+33,6+j*49+37))
                    * (int(next.slice(6+j*49+45,6+j*49+46)) - int(next.slice(6+j*49+46,6+j*49+47)));
            }
        }
        require(tx.outputs[1].tokenAmount == collateral);
        if (collateral == 0) { require(tx.outputs[1].tokenCategory == 0x); }
        else { require(tx.outputs[1].tokenCategory == stakingCategory); }
        require(value >= (periods - int(next.slice(0,4))) * cap + 1000);
        require(tx.outputs[0].nftCommitment == hash256(next));
        require(tx.outputs[0].value == value);
    }
}
